import 'dart:async';
import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/foundation.dart';
import 'package:gobarber/core/config/app_config.dart';
// Generated by `flutterfire configure`; git-ignored (see README).
import 'package:gobarber/firebase_options.dart';

/// Initializes Firebase once (safe across hot restarts) and checks that the generated
/// configuration points at the expected project ([AppConfig.firebaseProjectId]).
Future<FirebaseApp> initializeFirebase() async {
  final app = Firebase.apps.isNotEmpty
      ? Firebase.app()
      : await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
  final expected = AppConfig.firebaseProjectId;
  final actual = app.options.projectId;
  if (expected.isNotEmpty && expected != actual) {
    throw StateError('Firebase project mismatch: the app is configured for "$actual" but '
        'FIREBASE_PROJECT_ID is "$expected". Re-run flutterfire configure or fix the define.');
  }
  return app;
}

/// Called from main(). Returns true when Firebase is ready. Platforms that FlutterFire has not
/// configured (iOS, macOS, Windows, Linux) throw UnsupportedError; in mock/demo mode the app
/// then continues without Firebase (real sign-in is disabled there).
Future<bool> bootstrapFirebase() async {
  try {
    final app = await initializeFirebase();
    if (kDebugMode) {
      debugPrint('Firebase initialized: project=${app.options.projectId} app=${app.name}');
      unawaited(probeFirestore());
    }
    return true;
  } on UnsupportedError catch (e) {
    if (!AppConfig.useMockData) rethrow;
    debugPrint('Firebase not available on this platform, continuing in mock mode: ${e.message}');
    return false;
  }
}

/// Debug-only connectivity check. With production-mode rules a read of this document must be
/// DENIED: "permission-denied" proves the server was reached and the rules are locked down.
Future<void> probeFirestore() async {
  try {
    await FirebaseFirestore.instance
        .collection('_healthcheck')
        .doc('ping')
        .get()
        .timeout(const Duration(seconds: 10));
    debugPrint('Firestore probe: read was ALLOWED - review your security rules!');
  } on FirebaseException catch (e) {
    debugPrint(e.code == 'permission-denied'
        ? 'Firestore probe OK: server reached, rules deny access as expected'
        : 'Firestore probe: ${e.code} - ${e.message}');
  } on TimeoutException {
    debugPrint('Firestore probe: timed out (offline or blocked network?)');
  } catch (e) {
    debugPrint('Firestore probe failed: $e');
  }
}
